310	    while !data.is_empty() {
311	        let n = unsafe {
312	            libc::write(fd, data.as_ptr().cast::<libc::c_void>(), data.len())
313	        };
314	        if n < 0 {
315	            let e = std::io::Error::last_os_error();
316	            if e.raw_os_error() == Some(libc::EINTR) {
317	                continue;
318	            }
319	            return Err(e);
320	        }
