1	//! Regression coverage for keygen's write/sync contract on Unix: what must
2	//! hold while the 32 key bytes are being saved, and when saving cannot
3	//! complete (see README "文件权限" for the permission side, covered in
4	//! keygen_permissions.rs).
5	//!
6	//! What is protected here:
7	//!
8	//! * Partial writes: if the kernel only accepts part of the buffer per
9	//!   write() call, the remaining bytes still land -- no byte already written
10	//!   is duplicated, no later byte is skipped. The final file is exactly the
11	//!   32 raw key bytes (no newline, header, or trailer), mode 0600.
12	//! * Recoverable interruption: write() failing with EINTR and then
13	//!   succeeding still completes the same generation with exit code 0.
14	//! * Success is only reported after every byte is written *and* fsynced:
15	//!   exit 0, the usual "Key saved to ..." line on stdout, empty stderr.
16	//! * Unrecoverable write error after some bytes landed, and fsync failure
17	//!   after all bytes landed: exit 1, stderr explains the failure (naming
18	//!   the target), stdout carries no success message, the file created by
19	//!   this invocation is removed, and neither the parent directory's
20	//!   permissions nor pre-existing siblings are touched. Key bytes never
21	//!   appear on stdout/stderr, on success or on failure.
22	//! * Zero-byte write: write() accepting 0 bytes while bytes remain -- no
23	//!   progress, yet no errno either -- is neither success nor a recoverable
24	//!   interruption. Whether it happens before any byte landed or midway,
25	//!   the command must end (not hang in the save loop) with exit 1, an
26	//!   explanation naming the target on stderr, empty stdout, and no file
27	//!   left at the target: no empty file, no partial key, no zero-padded
28	//!   32-byte stand-in.
29	//! * Close-stage failure: all 32 bytes written and fsynced, then close()
30	//!   reporting an unrecoverable error is still a failed save -- exit 1,
31	//!   empty stdout, stderr naming the target and the close-stage error, and
32	//!   the file removed even though it holds 32 bytes with mode 0600. If the
33	//!   system also refuses the removal, stderr keeps the close failure and
34	//!   additionally warns that cleanup did not complete and this run's key
35	//!   file may remain at the target; the parent directory's permissions are
36	//!   never loosened to force the cleanup, and the key is not stashed under
37	//!   another name. A close() that merely reports EINTR after releasing the
38	//!   descriptor is not a failure: the save is reported as usual, exit 0.
39	//! * Refused cleanup after a write/fsync/permission-stage failure: the same
40	//!   reporting rule as for the close stage -- exit 1, empty stdout, stderr
41	//!   keeps the original failure reason (unfinished write, failed sync, or
42	//!   the 0600 permission problem), additionally reports the failed cleanup
43	//!   and its reason, and warns that this run's file (even an empty one) may
44	//!   still be present at the target so the user can check and remove it.
45	//!
46	//! The faults are injected by the LD_PRELOAD shim (tests/support/permfail),
47	//! which also traces every write()/fsync() on the key descriptor so the
48	//! byte stream can be checked for gaps, duplicates, and leaks.
49	#![cfg(unix)]
50	
51	use std::collections::HashMap;
52	use std::fs;
53	use std::os::unix::fs::{MetadataExt, PermissionsExt};
54	use std::path::{Path, PathBuf};
55	use std::process::Command;
56	use std::sync::atomic::{AtomicU64, Ordering};
57	
58	const KEY_LEN: usize = 32;
59	const MODE_0600: u32 = 0o600;
60	const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];
61	
62	fn bin() -> PathBuf {
63	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
64	}
65	
66	fn permfail_so() -> Option<PathBuf> {
67	    option_env!("WRAPFILE_PERMFAIL_SO").map(PathBuf::from)
68	}
69	
70	// ---------------------------------------------------------------------------
71	// scratch directory
72	// ---------------------------------------------------------------------------
73	
74	struct Tmp {
75	    path: PathBuf,
76	}
77	
78	impl Tmp {
79	    fn new(label: &str) -> Tmp {
80	        static SEQ: AtomicU64 = AtomicU64::new(0);
81	        let path = std::env::temp_dir().join(format!(
82	            "wrapfile-keygen-write-tests-{}-{}-{}",
83	            std::process::id(),
84	            label,
85	            SEQ.fetch_add(1, Ordering::Relaxed)
86	        ));
87	        fs::create_dir_all(&path).unwrap();
88	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
89	        Tmp { path }
90	    }
91	
92	    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
93	        self.path.join(name)
94	    }
95	}
96	
97	impl Drop for Tmp {
98	    fn drop(&mut self) {
99	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
100	        let _ = fs::remove_dir_all(&self.path);
101	    }
102	}
103	
104	// ---------------------------------------------------------------------------
105	// running the binary
106	// ---------------------------------------------------------------------------
107	
108	struct Run {
109	    rc: i32,
110	    out: Vec<u8>,
111	    err: Vec<u8>,
112	}
113	
114	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
115	/// wrapper, with the permfail shim preloaded and a trace file configured.
116	fn run_keygen(key: &Path, umask: u32, so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
117	    let mut cmd = Command::new("/bin/sh");
118	    cmd.arg("-c")
119	        .arg(format!("umask {umask:04o}; exec \"$@\""))
120	        .arg("sh")
121	        .arg(bin())
122	        .arg("keygen")
123	        .arg(key)
124	        .env("LD_PRELOAD", so)
125	        .env("WRAPFILE_TEST_TRACE_FILE", trace);
126	    for (k, v) in extra_env {
127	        cmd.env(k, v);
128	    }
129	    let o = cmd.output().unwrap();
130	    Run {
131	        rc: o.status.code().unwrap_or(-1),
132	        out: o.stdout,
133	        err: o.stderr,
134	    }
135	}
136	
137	// ---------------------------------------------------------------------------
138	// shim trace log
139	// ---------------------------------------------------------------------------
140	
141	struct Event {
142	    kind: String,
143	    attrs: HashMap<String, String>,
144	}
145	
146	impl Event {
147	    fn get(&self, key: &str) -> Option<&str> {
148	        self.attrs.get(key).map(String::as_str)
149	    }
150	
151	    fn ret(&self) -> Option<i64> {
152	        self.get("ret").and_then(|v| v.parse().ok())
153	    }
154	
155	    fn off(&self) -> Option<u64> {
156	        self.get("off").and_then(|v| v.parse().ok())
157	    }
158	
159	    fn hex_bytes(&self) -> Option<Vec<u8>> {
160	        let hex = self.get("hex")?;
161	        assert_eq!(hex.len() % 2, 0, "odd hex in trace line");
162	        Some(
163	            (0..hex.len() / 2)
164	                .map(|i| u8::from_str_radix(&hex[i * 2..i * 2 + 2], 16).unwrap())
165	                .collect(),
166	        )
167	    }
168	}
169	
170	fn parse_trace(path: &Path) -> Vec<Event> {
171	    let text = fs::read_to_string(path).unwrap();
172	    text.lines()
173	        .map(|line| {
174	            let mut it = line.split_whitespace();
175	            let kind = it.next().unwrap_or("").to_string();
176	            let attrs = it
177	                .filter_map(|kv| kv.split_once('=').map(|(k, v)| (k.to_string(), v.to_string())))
178	                .collect();
179	            Event { kind, attrs }
180	        })
181	        .collect()
182	}
183	
184	/// Create the trace file up front (mode 0644) so that it stays readable even
185	/// when the child runs under umask 0777 -- the shim opens it O_APPEND.
186	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
187	    let p = dir.join(name);
188	    fs::File::create(&p).unwrap();
189	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
190	    p
191	}
192	
193	/// The successful write() calls, in call order: (offset, bytes landed, bytes).
194	fn successful_writes(events: &[Event]) -> Vec<(u64, u64, Option<Vec<u8>>)> {
195	    events
196	        .iter()
197	        .filter(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
198	        .map(|e| {
199	            (
200	                e.off().expect("WRITE event needs off="),
201	                e.ret().unwrap() as u64,
202	                e.hex_bytes(),
203	            )
204	        })
205	        .collect()
206	}
207	
208	/// The landed writes must tile [0, total) exactly: the first starts at 0,
209	/// each continues where the previous ended -- no byte written twice, none
210	/// skipped.
211	fn assert_writes_tile(writes: &[(u64, u64, Option<Vec<u8>>)], total: usize, context: &str) {
212	    assert!(!writes.is_empty(), "{context}: no bytes were ever written");
213	    let mut expect = 0u64;
214	    for (off, n, _) in writes {
215	        assert_eq!(
216	            *off, expect,
217	            "{context}: write at offset {off} overlaps or leaves a gap (expected {expect})"
218	        );
219	        expect += n;
220	    }
221	    assert_eq!(
222	        expect as usize, total,
223	        "{context}: writes must add up to exactly {total} bytes, got {expect}"
224	    );
225	}
226	
227	fn reconstruct(writes: &[(u64, u64, Option<Vec<u8>>)]) -> Vec<u8> {
228	    writes
229	        .iter()
230	        .flat_map(|(_, _, hex)| hex.clone().expect("TRACE_BYTES must be on"))
231	        .collect()
232	}
233	
234	/// The write() calls that accepted 0 bytes while reporting no error.
235	fn zero_writes<'a>(events: &'a [Event]) -> Vec<&'a Event> {
236	    events
237	        .iter()
238	        .filter(|e| e.kind == "WRITE" && e.ret() == Some(0))
239	        .collect()
240	}
241	
242	/// Bytes the program handed to write() calls that accepted none of them.
243	fn rejected_offerings(events: &[Event]) -> Vec<u8> {
244	    zero_writes(events)
245	        .iter()
246	        .flat_map(|e| e.hex_bytes().expect("TRACE_BYTES must be on"))
247	        .collect()
248	}
249	
250	// ---------------------------------------------------------------------------
251	// filesystem assertions
252	// ---------------------------------------------------------------------------
253	
254	fn mode_of(path: &Path) -> u32 {
255	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
256	}
257	
258	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
259	    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
260	}
261	
262	/// The full success contract: exit 0, empty stderr, only the save-location
263	/// line on stdout, and exactly 32 raw key bytes in a 0600 file that leaks
264	/// nowhere.
265	fn assert_success(key: &Path, run: &Run) -> Vec<u8> {
266	    assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
267	    assert!(
268	        run.err.is_empty(),
269	        "stderr must be empty on success, got {}",
270	        String::from_utf8_lossy(&run.err)
271	    );
272	    assert_eq!(
273	        run.out,
274	        format!("Key saved to {}\n", key.display()).into_bytes(),
275	        "stdout must be exactly the save-location message"
276	    );
277	
278	    let meta = fs::metadata(key).expect("key file must exist on success");
279	    assert_eq!(meta.len() as usize, KEY_LEN, "key must be exactly 32 bytes");
280	    assert_eq!(
281	        meta.mode() & 0o7777,
282	        MODE_0600,
283	        "key file mode must be exactly 0600"
284	    );
285	
286	    let bytes = fs::read(key).unwrap();
287	    assert_eq!(bytes.len(), KEY_LEN);
288	    assert!(bytes.iter().any(|&b| b != 0), "key must not be all zeroes");
289	    assert!(
290	        !contains_slice(&run.out, &bytes) && !contains_slice(&run.err, &bytes),
291	        "key bytes must never appear on stdout/stderr"
292	    );
293	    bytes
294	}
295	
296	/// The failure contract shared by the write-error and fsync-error tests:
297	/// exit 1, an explanation on stderr, no success output, no leaked key
298	/// material, and no trace of this invocation left in the parent directory.
299	fn assert_failed_cleanly(
300	    key: &Path,
301	    run: &Run,
302	    dir: &Path,
303	    allowed_entries: &[&str],
304	    leaked_candidate: &[u8],
305	) {
306	    assert_eq!(run.rc, 1, "an unfinishable save must exit 1");
307	    assert!(
308	        run.out.is_empty(),
309	        "no success message may be printed on failure, got {}",
310	        String::from_utf8_lossy(&run.out)
311	    );
312	    assert!(!run.err.is_empty(), "stderr must explain the failure");
313	    let stderr = String::from_utf8_lossy(&run.err);
314	    assert!(
315	        stderr.contains(&key.display().to_string()),
316	        "stderr should name the target path, got: {stderr}"
317	    );
318	    assert!(
319	        !contains_slice(&run.out, leaked_candidate)
320	            && !contains_slice(&run.err, leaked_candidate),
321	        "key material must never leak to stdout/stderr, even on failure"
322	    );
323	
324	    assert!(
325	        !key.exists(),
326	        "the file this invocation created must be removed after the failure"
327	    );
328	    let mut leftovers: Vec<String> = fs::read_dir(dir)
329	        .unwrap()
330	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
331	        .filter(|n| !allowed_entries.contains(&n.as_str()))
332	        .collect();
333	    leftovers.sort();
334	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
335	}
336	
337	/// Key material must not surface on stdout/stderr in any encoding: not as
338	/// raw bytes, and not as a hex (or other text) rendering.
339	fn assert_key_material_not_leaked(run: &Run, material: &[u8], what: &str) {
340	    assert!(
341	        !contains_slice(&run.out, material) && !contains_slice(&run.err, material),
342	        "{what} must never appear on stdout/stderr as raw bytes"
343	    );
344	    let hex: String = material.iter().map(|b| format!("{b:02x}")).collect();
345	    let out = String::from_utf8_lossy(&run.out);
346	    let err = String::from_utf8_lossy(&run.err);
347	    assert!(
348	        !out.contains(&hex) && !err.contains(&hex),
349	        "{what} must never appear on stdout/stderr in hex form"
350	    );
351	}
352	
353	/// The contract when the save fails AND the system refuses to remove this
354	/// run's file: exit 1, empty stdout, stderr names the target, keeps the
355	/// original failure reason (`stage_reason`), reports the refused cleanup,
356	/// and warns that this run's file may remain -- and the file really does
357	/// remain, with nothing stashed under another name.
358	fn assert_failed_with_residue(
359	    key: &Path,
360	    run: &Run,
361	    dir: &Path,
362	    allowed_entries: &[&str],
363	    stage_reason: &str,
364	) {
365	    assert_eq!(run.rc, 1, "a failed save with refused cleanup must exit 1");
366	    assert!(
367	        run.out.is_empty(),
368	        "no success message may be printed, got {}",
369	        String::from_utf8_lossy(&run.out)
370	    );
371	    let stderr = String::from_utf8_lossy(&run.err);
372	    assert!(
373	        stderr.contains(&key.display().to_string()),
374	        "stderr should name the target path, got: {stderr}"
375	    );
376	    // The original failure reason is still reported...
377	    assert!(
378	        stderr.contains(stage_reason),
379	        "stderr must keep the original failure reason ({stage_reason:?}), got: {stderr}"
380	    );
381	    // ...the cleanup failure is reported too (not silently dropped, and not
382	    // replacing the save error)...
383	    assert!(
384	        stderr.contains("cleanup"),
385	        "stderr must report the failed cleanup, got: {stderr}"
386	    );
387	    // ...and the user is told this run's file may remain -- never that it
388	    // is gone.
389	    assert!(
390	        stderr.contains("may still be present"),
391	        "stderr must warn that this run's file may remain, got: {stderr}"
392	    );
393	
394	    // The refused removal means this run's file really is still at the
395	    // target -- the warning above is what keeps it from being mistaken for
396	    // a successfully saved key.
397	    assert!(
398	        key.exists(),
399	        "with unlink refused, this run's file remains at the target"
400	    );
401	    // Nothing was stashed under another name and no other residue appeared.
402	    let mut expected: Vec<String> = allowed_entries.iter().map(|s| s.to_string()).collect();
403	    expected.push(key.file_name().unwrap().to_string_lossy().into_owned());
404	    expected.sort();
405	    let mut entries: Vec<String> = fs::read_dir(dir)
406	        .unwrap()
407	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
408	        .collect();
409	    entries.sort();
410	    assert_eq!(entries, expected, "no renamed copy or other leftover may appear");
411	}
