413	// A pre-existing object that must survive a failed keygen byte-for-byte.
414	struct Sentinel {
415	    path: PathBuf,
416	    bytes: Vec<u8>,
417	    mode: u32,
418	    inode: u64,
419	}
420	
421	impl Sentinel {
422	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
423	        let path = dir.join(name);
424	        fs::write(&path, bytes).unwrap();
425	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
426	        let meta = fs::metadata(&path).unwrap();
427	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
428	    }
429	
430	    fn assert_untouched(&self) {
431	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
432	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
433	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
434	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
435	    }
436	}
