442	#[test]
443	fn partial_writes_save_the_full_key_exactly_once() {
444	    let Some(so) = permfail_so() else {
445	        eprintln!("skipping: permfail shim not available on this target");
446	        return;
447	    };
448	
449	    for umask in UMASKS {
450	        let tmp = Tmp::new("partial");
451	        let key = tmp.child("key");
452	        let trace = prepare_trace(&tmp.path, "trace.log");
453	
454	        // The kernel accepts only one byte per write() call.
455	        let run = run_keygen(
456	            &key,
457	            umask,
458	            &so,
459	            &[
460	                ("WRAPFILE_TEST_PARTIAL_WRITE", "1"),
461	                ("WRAPFILE_TEST_TRACE_BYTES", "1"),
462	            ],
463	            &trace,
464	        );
465	
466	        let on_disk = assert_success(&key, &run);
467	
468	        let events = parse_trace(&trace);
469	        let writes = successful_writes(&events);
470	        assert!(
471	            writes.len() >= KEY_LEN,
472	            "one-byte writes should mean at least 32 write() calls, got {}",
473	            writes.len()
474	        );
475	        // No written byte repeated, no later byte dropped...
476	        assert_writes_tile(&writes, KEY_LEN, "partial writes");
477	        // ...and the bytes the program handed to the kernel are exactly the
478	        // bytes that ended up in the file -- nothing reordered or invented.
479	        assert_eq!(
480	            reconstruct(&writes),
481	            on_disk,
482	            "file content must equal the concatenation of the write() calls"
483	        );
484	
485	        // Success was reported only after the data was synced to disk.
486	        let last_write = events
487	            .iter()
488	            .rposition(|e| e.kind == "WRITE" && e.ret().is_some_and(|r| r > 0))
489	            .unwrap();
490	        let fsynced = events
491	            .iter()
492	            .position(|e| e.kind == "FSYNC" && e.ret() == Some(0))
493	            .expect("the key must be fsynced before success is reported");
494	        assert!(fsynced > last_write, "fsync must follow the last write");
495	    }
496	}
