```rust
/// The save could not be completed: remove the file this invocation created
/// and build the error to report. `stage` is the original failure (its kind
/// and message are preserved in the report). If `fd` is still open it is
/// closed after the unlink, whose result is captured first because close may
/// clobber errno; on Linux close releases the descriptor even when it
/// reports an error, so it is never retried.
///
/// The unlink only ever targets the link created by this invocation (the
/// caller opened it O_CREAT | O_EXCL), never an object that predates this
/// run. If the system refuses the removal, the report keeps the original
/// failure, adds the cleanup failure and its reason, and says plainly that
/// a file from this failed run may still sit at the target -- whether it is
/// an empty file, a partial key, or 32 unsynced bytes, it is not a saved
/// key. The refusal is never worked around (no loosening of the parent
/// directory's permissions, no stashing the key under another name).
#[cfg(unix)]
fn abort_save(
    c_path: &CString,
    path: &OsStr,
    fd: Option<RawFd>,
    stage: std::io::Error,
) -> std::io::Error {
    let unlink_err = if unsafe { libc::unlink(c_path.as_ptr()) } == 0 {
        None
    } else {
        Some(std::io::Error::last_os_error())
    };
    if let Some(fd) = fd {
        unsafe { libc::close(fd) };
    }
    let kind = stage.kind();
    match unlink_err {
        None => std::io::Error::new(
            kind,
            format!(
                "key file '{}' was not saved: {stage}; the file created by \
                 this invocation has been removed",
                display_path(path)
            ),
        ),
        Some(ue) => std::io::Error::new(
            kind,
            format!(
                "key file '{}' was not saved: {stage}; cleanup of the \
                 incomplete file also failed ({ue}): a file created by this \
                 failed run may still be present at the target -- check and \
                 remove it yourself",
                display_path(path)
            ),
        ),
    }
}
```

